// NewLogsDecoder returns a LogsDecoder that processes CloudTrail logs from the provided reader.
// The source format is auto-detected from the first JSON key:
//   - S3 Records format: supports offset-based streaming. The offset tracks the number of
//     records processed so far; WithOffset skips that many records before decoding begins.
//   - CloudWatch subscription filter and digest formats: these are decoded as a single payload
//     and do not support resuming from an arbitrary position. When a non-zero offset is provided
//     the stream is treated as already consumed: the first DecodeLogs call returns io.EOF and
//     Offset reports the number of bytes consumed from the input.
func (u *CloudTrailLogUnmarshaler) NewLogsDecoder(reader io.Reader, options ...encoding.DecoderOption) (encoding.LogsDecoder, error) {
	opts := encoding.NewDecoderOptions(options...)

	bufferedReader := bufio.NewReaderSize(reader, readerBufferSize)

	// Peek into the first 64 bytes to determine the type of CloudTrail log.
	peekBytes, err := bufferedReader.Peek(64)
	if err != nil && !errors.Is(err, io.EOF) {
		return nil, fmt.Errorf("failed to peek into CloudTrail log: %w", err)
	}

	firstKey, err := extractFirstKey(peekBytes)
	if err != nil {
		return nil, fmt.Errorf("failed to extract the first JSON key: %w", err)
	}

	// S3 CloudTrail logs (top-level "Records" array) support record-based streaming.
	if firstKey == "Records" {
		return u.newS3StreamDecoder(bufferedReader, options...)
	}

	// CloudWatch subscription filter and digest formats are decoded as a whole.
	decoder := gojson.NewDecoder(bufferedReader)

	// A non-zero offset means the caller is trying to resume a stream that cannot be
	// resumed for these formats. Consume the payload to report the number of bytes read
	// and return io.EOF immediately.
	if opts.Offset != 0 {
		var raw gojson.RawMessage
		if err := decoder.Decode(&raw); err != nil {
			return nil, fmt.Errorf("failed to read the input stream: %w", err)
		}

		consumed := decoder.InputOffset()
		return xstreamencoding.NewLogsDecoderAdapter(
			func() (plog.Logs, error) {
				return plog.NewLogs(), io.EOF
			},
			func() int64 {
				return consumed
			},
		), nil
	}

	var logs plog.Logs
	if isCloudWatchKey(firstKey) {
		logs, err = u.decodeCloudWatch(decoder)
	} else {
		var cloudTrailDigest CloudTrailDigest
		if err = decoder.Decode(&cloudTrailDigest); err != nil {
			return nil, fmt.Errorf("failed to unmarshal payload as a CloudTrail digest: %w", err)
		}
		logs, err = u.processDigestRecord(cloudTrailDigest)
	}
	if err != nil {
		return nil, err
	}

	offset := decoder.InputOffset()
	flushed := false
	return xstreamencoding.NewLogsDecoderAdapter(
		func() (plog.Logs, error) {
			if flushed {
				return plog.NewLogs(), io.EOF
			}
			flushed = true
			return logs, nil
		},
		func() int64 {
			return offset
		},
	), nil
}

// newS3StreamDecoder returns a LogsDecoder that streams CloudTrail records from a
